import os

base_workspace = "/home/USER/runs/paper/qwen-hpl0-u1-turns/frozen/seen-reference-3/play/users/u001/system/state"

def list_files(directory, max_depth=3, prefix=""):
    """Recursively list files in directory up to max_depth levels"""
    files = []
    try:
        items = sorted(os.listdir(directory))
    except:
        return files

    for item in items:
        full_path = os.path.join(directory, item)
        if os.path.isfile(full_path):
            rel_path = os.path.relpath(full_path, base_workspace)
            files.append(f"{prefix}{rel_path}")
        else:
            if max_depth > 0:
                files.extend(list_files(full_path, max_depth - 1, prefix + "  "))

    return files

all_files = list_files(base_workspace)
print("All files in workspace:")
for f in all_files:
    print(f"  {f}")

